// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.LinkedHashMap;
import java.util.List;

import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.junit.jupiter.api.Test;

/**
 * M-A0 value-checked bind: where independently obtained ids meet in one slot, a raw-id mismatch must consult RDF term
 * equality through the evaluation's authority before rejecting — a store id and a runtime-interned id can denote the
 * same term (language tags compare case-insensitively). On a raw store source exact id equality IS term equality, so
 * the check degrades to today's bind.
 */
public class LmdbNativeValueCheckedBindTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	public void mismatchedIdsForTheSameTermBindThroughTheAuthority() {
		LmdbNativeRowDetachmentTest.FakeStoreSource store = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		long storeId = store.add(VF.createLiteral("hello", "en"));
		SyntheticValueSource evalSource = new SyntheticValueSource(store, PlanValueCatalog.EMPTY).forEvaluation();
		// the case-different spelling misses the byte-exact store and interns — same RDF term, different id
		long internedId = evalSource.authority().idOfOrIntern(VF.createLiteral("hello", "EN"));
		assertThat(internedId).isNotEqualTo(storeId);

		RowState row = row(evalSource);
		assertThat(row.bindOrCheckTerm(0, storeId)).isTrue();
		assertThat(row.bindOrCheckTerm(0, storeId)).as("exact rebind stays true").isTrue();
		assertThat(row.bindOrCheckTerm(0, internedId))
				.as("an id mismatch for the same RDF term must not reject the row")
				.isTrue();
		assertThat(row.slots[0]).as("the slot keeps its current id when the terms agree").isEqualTo(storeId);
		long otherId = evalSource.authority().idOfOrIntern(VF.createLiteral("different"));
		assertThat(row.bindOrCheckTerm(0, otherId)).as("a genuine term mismatch still rejects").isFalse();
	}

	@Test
	public void rawStoreSourceKeepsExactIdSemantics() {
		LmdbNativeRowDetachmentTest.FakeStoreSource store = new LmdbNativeRowDetachmentTest.FakeStoreSource();
		long first = store.add(VF.createLiteral("hello", "en"));
		long second = store.add(VF.createLiteral("hello", "EN"));

		RowState row = row(store);
		assertThat(row.bindOrCheckTerm(0, first)).isTrue();
		assertThat(row.bindOrCheckTerm(0, second))
				.as("without an evaluation authority the value-checked bind degrades to exact id equality")
				.isFalse();
	}

	/** Row with seeder-normalized slots (the seeder fills {@code UNKNOWN}; a raw row starts at the 0 sentinel). */
	private static RowState row(NativeLmdbQuerySource source) {
		LinkedHashMap<String, Integer> names = new LinkedHashMap<>();
		names.put("x", 0);
		NativeSlotLayout layout = new NativeSlotLayout(names, null);
		layout.freeze(List.of("x"));
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance());
		NativeRowSeeder.seed(row.slots, layout, EmptyBindingSet.getInstance(), source);
		row.recomputeBoundMask();
		return row;
	}
}
